using System;

namespace Framework.AI.Core
{
    /// <summary>
    /// 自律型エージェントの基本的な稼働管理を提供する。
    /// </summary>
    /// <typeparam name="TParameter">
    /// パラメーターを識別する型。
    /// </typeparam>
    /// <remarks>
    /// Unityのフレーム更新には直接依存しない。
    /// 更新管理システムまたは外部の制御元から更新する。
    /// メインスレッドからの利用を想定する。
    /// </remarks>
    public abstract class AgentBase<TParameter> : IAgent
    {
        /// <summary>
        /// エージェントの共有情報。
        /// </summary>
        private AgentContext<TParameter> context;

        /// <summary>
        /// 現在の稼働状態。
        /// </summary>
        private AgentState state =
            AgentState.Uninitialized;

        /// <summary>
        /// 更新処理を実行しているかどうか。
        /// </summary>
        private bool isTicking;

        /// <summary>
        /// 状態遷移処理を実行しているかどうか。
        /// </summary>
        private bool isTransitioning;

        /// <summary>
        /// 実行した更新処理の累計件数。
        /// </summary>
        private long tickCount;

        /// <summary>
        /// 更新処理に渡された累計時間。単位は秒。
        /// </summary>
        private double elapsedTickTime;

        /// <summary>
        /// エージェント固有の識別子を取得する。
        /// 未初期化の場合は空の識別子を返す。
        /// </summary>
        public Guid Id =>
            context == null ? Guid.Empty : context.Id;

        /// <summary>
        /// エージェントの表示名を取得する。
        /// 未初期化の場合は空文字列を返す。
        /// </summary>
        public string Name =>
            context == null ? string.Empty : context.Name;

        /// <summary>
        /// エージェントの共有情報を取得する。
        /// 未初期化の場合はnullを返す。
        /// </summary>
        public AgentContext<TParameter> Context => context;

        /// <summary>
        /// 現在の稼働状態を取得する。
        /// </summary>
        public AgentState State => state;

        /// <summary>
        /// 現在初期化済みで利用可能かどうかを取得する。
        /// </summary>
        public bool IsInitialized =>
            state == AgentState.Inactive ||
            state == AgentState.Active ||
            state == AgentState.Paused;

        /// <summary>
        /// 稼働中かどうかを取得する。
        /// </summary>
        public bool IsActive =>
            state == AgentState.Active;

        /// <summary>
        /// 一時停止中かどうかを取得する。
        /// </summary>
        public bool IsPaused =>
            state == AgentState.Paused;

        /// <summary>
        /// 破棄済みかどうかを取得する。
        /// </summary>
        public bool IsDisposed =>
            state == AgentState.Disposed;

        /// <summary>
        /// 現在更新処理を実行可能かどうかを取得する。
        /// </summary>
        public bool IsTickEnabled =>
            IsActive &&
            !isTransitioning &&
            context != null &&
            !context.Parameters.IsDisposed;

        /// <summary>
        /// 更新処理の累計実行件数を取得する。
        /// </summary>
        public long TickCount => tickCount;

        /// <summary>
        /// 更新処理に渡された累計時間を取得する。
        /// 単位は秒。
        /// </summary>
        public double ElapsedTickTime => elapsedTickTime;

        /// <summary>
        /// 稼働状態が変更された際に発生する。
        /// 引数は変更前の状態、変更後の状態の順となる。
        /// </summary>
        public event Action<AgentState, AgentState>
            StateChanged;

        /// <summary>
        /// エージェントを初期化する。
        /// </summary>
        /// <param name="newContext">個体固有の共有情報</param>
        /// <returns>初期化に成功した場合はtrue</returns>
        /// <remarks>
        /// 初期化後は非稼働状態となる。
        /// 同一インスタンスの再初期化は行わない。
        /// </remarks>
        public bool Initialize(
            AgentContext<TParameter> newContext)
        {
            EnsureCanTransition();

            if (newContext == null)
            {
                throw new ArgumentNullException(
                    nameof(newContext));
            }

            if (state != AgentState.Uninitialized)
            {
                return false;
            }

            if (newContext.Parameters.IsDisposed)
            {
                throw new ObjectDisposedException(
                    nameof(newContext.Parameters));
            }

            isTransitioning = true;

            try
            {
                context = newContext;

                try
                {
                    // 派生クラス固有の初期化を実行する。
                    OnInitialize();
                }
                catch
                {
                    // 初期化に失敗した場合は共有情報を解除する。
                    context = null;

                    throw;
                }

                ChangeState(AgentState.Inactive);

                return true;
            }
            finally
            {
                isTransitioning = false;
            }
        }

        /// <summary>
        /// エージェントを稼働状態にする。
        /// </summary>
        /// <returns>状態変更に成功した場合はtrue</returns>
        public bool Activate()
        {
            EnsureCanTransition();

            if (state != AgentState.Inactive ||
                context.Parameters.IsDisposed)
            {
                return false;
            }

            TransitionTo(
                AgentState.Active,
                OnActivated);

            return true;
        }

        /// <summary>
        /// エージェントを非稼働状態にする。
        /// </summary>
        /// <returns>状態変更に成功した場合はtrue</returns>
        public bool Deactivate()
        {
            EnsureCanTransition();

            if (state != AgentState.Active &&
                state != AgentState.Paused)
            {
                return false;
            }

            TransitionTo(
                AgentState.Inactive,
                OnDeactivated);

            return true;
        }

        /// <summary>
        /// エージェントの稼働を一時停止する。
        /// </summary>
        /// <returns>状態変更に成功した場合はtrue</returns>
        public bool Pause()
        {
            EnsureCanTransition();

            if (state != AgentState.Active)
            {
                return false;
            }

            TransitionTo(
                AgentState.Paused,
                OnPaused);

            return true;
        }

        /// <summary>
        /// 一時停止中のエージェントを再開する。
        /// </summary>
        /// <returns>状態変更に成功した場合はtrue</returns>
        public bool Resume()
        {
            EnsureCanTransition();

            if (state != AgentState.Paused ||
                context.Parameters.IsDisposed)
            {
                return false;
            }

            TransitionTo(
                AgentState.Active,
                OnResumed);

            return true;
        }

        /// <summary>
        /// エージェントの更新処理を実行する。
        /// </summary>
        /// <param name="deltaTime">
        /// 前回更新からの経過時間。単位は秒。
        /// </param>
        /// <exception cref="ArgumentOutOfRangeException">
        /// 経過時間が不正な場合に発生する。
        /// </exception>
        /// <exception cref="InvalidOperationException">
        /// 更新処理が再入された場合に発生する。
        /// </exception>
        public void Tick(float deltaTime)
        {
            if (float.IsNaN(deltaTime) ||
                float.IsInfinity(deltaTime) ||
                deltaTime < 0f)
            {
                throw new ArgumentOutOfRangeException(
                    nameof(deltaTime));
            }

            if (isTicking)
            {
                throw new InvalidOperationException(
                    "更新処理を再入できません。");
            }

            if (!IsTickEnabled || deltaTime == 0f)
            {
                return;
            }

            isTicking = true;

            try
            {
                // 派生クラス固有の更新処理を実行する。
                OnTick(deltaTime);

                // 正常に完了した更新のみを集計する。
                tickCount++;

                elapsedTickTime += deltaTime;
            }
            finally
            {
                isTicking = false;
            }
        }

        /// <summary>
        /// エージェントを破棄する。
        /// </summary>
        /// <remarks>
        /// 派生クラス固有の解放処理を実行する。
        /// 外部から渡されたパラメーター集合は破棄しない。
        /// </remarks>
        public void Dispose()
        {
            if (IsDisposed)
            {
                return;
            }

            EnsureCanTransition();

            isTransitioning = true;

            try
            {
                try
                {
                    OnDispose();
                }
                finally
                {
                    ChangeState(AgentState.Disposed);
                }
            }
            finally
            {
                // イベント購読と共有情報の参照を解放する。
                StateChanged = null;

                context = null;

                isTransitioning = false;
            }
        }

        /// <summary>
        /// 指定された稼働状態への遷移を実行する。
        /// </summary>
        /// <param name="newState">遷移先の状態</param>
        /// <param name="callback">状態遷移前の処理</param>
        private void TransitionTo(
            AgentState newState,
            Action callback)
        {
            isTransitioning = true;

            try
            {
                // 固有処理の完了後に状態を確定する。
                callback?.Invoke();

                ChangeState(newState);
            }
            finally
            {
                isTransitioning = false;
            }
        }

        /// <summary>
        /// 稼働状態を変更し、変更通知を発生させる。
        /// </summary>
        /// <param name="newState">変更後の状態</param>
        private void ChangeState(AgentState newState)
        {
            if (state == newState)
            {
                return;
            }

            AgentState previousState = state;

            state = newState;

            // 状態を更新してから購読者に通知する。
            StateChanged?.Invoke(
                previousState,
                newState);
        }

        /// <summary>
        /// 現在状態遷移を実行可能か検証する。
        /// </summary>
        /// <exception cref="InvalidOperationException">
        /// 状態遷移中または更新処理中の場合に発生する。
        /// </exception>
        private void EnsureCanTransition()
        {
            if (isTransitioning || isTicking)
            {
                throw new InvalidOperationException(
                    "状態遷移中または更新処理中は変更できません。");
            }
        }

        /// <summary>
        /// 派生クラス固有の初期化処理を実行する。
        /// </summary>
        protected virtual void OnInitialize()
        {
        }

        /// <summary>
        /// 稼働開始前の固有処理を実行する。
        /// </summary>
        protected virtual void OnActivated()
        {
        }

        /// <summary>
        /// 稼働停止前の固有処理を実行する。
        /// </summary>
        protected virtual void OnDeactivated()
        {
        }

        /// <summary>
        /// 一時停止前の固有処理を実行する。
        /// </summary>
        protected virtual void OnPaused()
        {
        }

        /// <summary>
        /// 稼働再開前の固有処理を実行する。
        /// </summary>
        protected virtual void OnResumed()
        {
        }

        /// <summary>
        /// 派生クラス固有の更新処理を実行する。
        /// </summary>
        /// <param name="deltaTime">
        /// 前回更新からの経過時間。単位は秒。
        /// </param>
        protected abstract void OnTick(float deltaTime);

        /// <summary>
        /// 派生クラス固有の解放処理を実行する。
        /// </summary>
        protected virtual void OnDispose()
        {
        }
    }
}
